const REGION_BY_CODE = new Map(ADMIN_REGIONS.map((region) => [region.code, region]));

export function getAdministrativeRegion(code) {
  const region = REGION_BY_CODE.get(String(code || ""));
  return region ? { ...region } : null;
}

export function listAdministrativeRegions() {
  return ADMIN_REGIONS.map((region) => ({ ...region }));
}

export function formatAdministrativeRegion(region) {
  if (!region) return "";
  return [region.province, region.city, region.district].filter(Boolean).join(" ");
}

function normalizeRegionPart(value) {
  let text = String(value || "").trim().replace(/\s+/g, "");
  if (!text) return "";
  for (const suffix of ["特别行政区", "自治区", "自治州", "地区", "盟", "省", "市", "区", "县", "旗", "州"]) {
    if (text.endsWith(suffix) && text.length > suffix.length) {
      text = text.slice(0, -suffix.length);
      break;
    }
  }
  return text;
}

function regionPartMatches(input, actual) {
  const left = String(input || "").trim();
  const right = String(actual || "").trim();
  return !!left && (left === right || normalizeRegionPart(left) === normalizeRegionPart(right));
}

export function findAdministrativeRegion(location) {
  const parts = String(location || "").trim().split(/\s+/).filter(Boolean);
  if (!parts.length) return null;

  let matches = [];
  if (parts.length >= 3) {
    const province = parts[parts.length - 3];
    const city = parts[parts.length - 2];
    const district = parts[parts.length - 1];
    matches = ADMIN_REGIONS.filter((region) =>
      regionPartMatches(province, region.province) &&
      regionPartMatches(city, region.city) &&
      regionPartMatches(district, region.district)
    );
  }
  if (matches.length !== 1 && parts.length >= 2) {
    const city = parts[parts.length - 2];
    const district = parts[parts.length - 1];
    matches = ADMIN_REGIONS.filter((region) =>
      regionPartMatches(city, region.city) && regionPartMatches(district, region.district)
    );
  }
  if (matches.length !== 1 && parts.length >= 2) {
    const province = parts[parts.length - 2];
    const district = parts[parts.length - 1];
    matches = ADMIN_REGIONS.filter((region) =>
      regionPartMatches(province, region.province) && regionPartMatches(district, region.district)
    );
  }
  if (matches.length !== 1 && parts.length === 1) {
    matches = ADMIN_REGIONS.filter((region) => regionPartMatches(parts[0], region.district));
  }
  return matches.length === 1 ? { ...matches[0] } : null;
}
